<script lang="ts">
  import { onMount } from 'svelte'; import { goto } from '$app/navigation'; import { api } from '$lib/api'; import { apiError, type StudentSession } from '$lib/student-session';
  let session: StudentSession | null = null; let accepted = false; let error = ''; let loading = true; let saving = false;
  onMount(async () => { try { session = await api<StudentSession>('/api/student/auth/me'); if (session.passwordChangeRequired) await goto('/student/password'); else if (!session.disclaimerRequired) await goto('/student'); } catch { await goto('/student/login'); } finally { loading = false; } });
  async function submit() { if (!accepted) return; saving = true; error = ''; try { await api('/api/student/disclaimer', { method: 'POST', body: JSON.stringify({ accepted: true }) }); await goto('/student'); } catch (e) { error = apiError(e); } finally { saving = false; } }
</script>
<svelte:head><title>Task Karate | Profile acknowledgment</title></svelte:head>
<main class="auth-stage"><section class="disclaimer-frame">{#if loading}<p>Checking your secure session…</p>{:else}<span class="student-eyebrow">PROFILE ACCESS / FINAL STEP</span><h1>Before you open<br />{session?.displayName ?? 'your'}’s page.</h1><p>Review this acknowledgment each time the supervised student profile is opened.</p><label class="acknowledgment"><input type="checkbox" bind:checked={accepted} /><span>I understand that this profile contains student information and should only be viewed by the student, guardian, or authorized staff.</span></label><div class="disclaimer-note">This is a local workflow acknowledgment, not a legal waiver or security boundary.</div>{#if error}<div class="error" role="alert">{error}</div>{/if}<div class="disclaimer-actions"><a class="outline-button" href="/schedule">Cancel</a><button class="primary-button" disabled={!accepted || saving} on:click={submit}>{saving ? 'Opening…' : 'Accept & open profile'}</button></div>{/if}</section></main>
